function aceMessage(text, title, icon) {
   (new MessageBox(text, title || ACE_TOOL_NAME + " " + ACE_VERSION, icon || StdIcon_Information, StdButton_Ok)).execute();
}

function aceHostIsWindows() {
   try {
      var paths = [
         String(File.systemTempDirectory || ""),
         String(File.homeDirectory || ""),
         String(File.currentWorkingDirectory || "")
      ];
      for (var i = 0; i < paths.length; ++i) {
         if (/^[A-Za-z]:[\\\/]/.test(paths[i]) || paths[i].indexOf("\\") >= 0)
            return true;
      }
      if (typeof CoreApplication !== "undefined" && CoreApplication.platform) {
         var platform = String(CoreApplication.platform).toLowerCase();
         if (platform.indexOf("win") >= 0)
            return true;
      }
      return false;
   } catch (error) {
      return false;
   }
}

function aceDefaultDialogSize() {
   return {
      width: ACE_DISPLAY_MIN_WIDTH,
      height: ACE_DISPLAY_MIN_HEIGHT
   };
}

function aceAcmCompactDialogSizeForWorkspace(workspace) {
   if (!ACE_HOST_IS_WINDOWS || !workspace)
      return aceDefaultDialogSize();
   return {
      width: Math.max(ACE_DISPLAY_MIN_WIDTH, Math.min(ACE_ACM_COMPACT_WINDOWS_MAX_WIDTH, Math.floor(workspace.width - ACE_ACM_COMPACT_WINDOWS_MARGIN_WIDTH))),
      height: Math.max(ACE_DISPLAY_MIN_HEIGHT, Math.min(ACE_ACM_COMPACT_WINDOWS_MAX_HEIGHT, Math.floor(workspace.height - ACE_ACM_COMPACT_WINDOWS_MARGIN_HEIGHT)))
   };
}

function aceMinimumSavedWindowWidthForPlatform() {
   return ACE_DISPLAY_MIN_WIDTH;
}

function aceSavedWindowSizeIsUsableForPlatform(saved) {
   if (!saved)
      return false;
   if (saved.width < aceMinimumSavedWindowWidthForPlatform())
      return false;
   if (saved.height < ACE_DISPLAY_MIN_HEIGHT)
      return false;
   if (ACE_HOST_IS_WINDOWS && saved.width <= ACE_DISPLAY_MIN_WIDTH + 8 && saved.height > ACE_ACM_COMPACT_WINDOWS_MAX_HEIGHT)
      return false;
   return true;
}

function aceFormatScreenSizeForWarning(size) {
   if (!size)
      return "unavailable";
   return Math.round(size.width || 0) + " x " + Math.round(size.height || 0);
}

function aceGetOptionalDialogRect(dialog, propertyName) {
   if (!dialog)
      return null;
   try {
      return (propertyName in dialog) ? dialog[propertyName] : null;
   } catch (error) {
      return null;
   }
}

function aceGetOptionalDialogNumber(dialog, propertyName) {
   if (!dialog)
      return null;
   try {
      var value = (propertyName in dialog) ? dialog[propertyName] : null;
      return typeof value === "number" && isFinite(value) ? value : null;
   } catch (error) {
      return null;
   }
}

function aceGetDialogPosition(dialog) {
   if (!dialog)
      return null;
   try {
      if ("position" in dialog && dialog.position && typeof dialog.position.x === "number" && typeof dialog.position.y === "number")
         return { x: Math.round(dialog.position.x), y: Math.round(dialog.position.y) };
   } catch (error1) {
   }
   var x = aceGetOptionalDialogNumber(dialog, "x");
   var y = aceGetOptionalDialogNumber(dialog, "y");
   if (x !== null && y !== null)
      return { x: Math.round(x), y: Math.round(y) };
   return null;
}

function aceGetDialogAvailableScreenSize(dialog) {
   var candidates = [
      aceGetOptionalDialogRect(dialog, "availableScreenRect"),
      aceGetOptionalDialogRect(dialog, "availableScreenBounds"),
      aceGetOptionalDialogRect(dialog, "availableRect"),
      aceGetOptionalDialogRect(dialog, "screenRect"),
      aceGetOptionalDialogRect(dialog, "screenBounds")
   ];
   for (var i = 0; i < candidates.length; ++i) {
      var rect = candidates[i];
      if (rect && typeof rect.width === "number" && typeof rect.height === "number" && rect.width > 0 && rect.height > 0)
         return { width: rect.width, height: rect.height };
   }
   return null;
}

function aceDisplayPlatformName() {
   return ACE_HOST_IS_WINDOWS ? "Windows" : "macOS / Unix";
}

function aceReadSettingInt(key) {
   if (typeof Settings === "undefined")
      return null;
   try {
      var value = Settings.read(key, DataType_Int32);
      var numeric = Number(value);
      return isFinite(numeric) ? Math.round(numeric) : null;
   } catch (error) {
      return null;
   }
}

function aceReadSettingBool(key) {
   if (typeof Settings === "undefined")
      return false;
   try {
      var value = Settings.read(key, DataType_Int32);
      var numeric = Number(value);
      return isFinite(numeric) && numeric !== 0;
   } catch (error) {
      return false;
   }
}

function aceWriteSettingBool(key, value) {
   if (typeof Settings === "undefined")
      return false;
   try {
      Settings.write(key, DataType_Int32, value ? 1 : 0);
      return true;
   } catch (error) {
   }
   return false;
}

function aceWriteSettingInt(key, value) {
   if (typeof Settings === "undefined")
      return false;
   try {
      Settings.write(key, DataType_Int32, Math.round(value || 0));
      return true;
   } catch (error) {
   }
   return false;
}

function aceFlushSettingsIfSupported() {
   if (typeof Settings === "undefined")
      return;
   try {
      if (typeof Settings.flush === "function")
         Settings.flush();
   } catch (error) {
   }
}

function aceWindowLayoutFallbackPath() {
   if (typeof File === "undefined")
      return null;
   try {
      var home = String(File.homeDirectory || "");
      if (!home)
         home = String(File.systemTempDirectory || "");
      if (!home)
         return null;
      while (home.length > 1 && (home.charAt(home.length - 1) === "/" || home.charAt(home.length - 1) === "\\"))
         home = home.substring(0, home.length - 1);
      return home + "/" + ACE_WINDOW_LAYOUT_FALLBACK_FILE;
   } catch (error) {
   }
   return null;
}

function aceWindowLayoutFromText(text) {
   if (!text)
      return null;
   var values = {};
   var lines = String(text).split(/\r?\n/);
   for (var i = 0; i < lines.length; ++i) {
      var line = lines[i];
      var eq = line.indexOf("=");
      if (eq <= 0)
         continue;
      values[line.substring(0, eq)] = line.substring(eq + 1);
   }
   var w = Number(values.width);
   var h = Number(values.height);
   if (!isFinite(w) || !isFinite(h) || w <= 0 || h <= 0)
      return null;
   var x = Number(values.x);
   var y = Number(values.y);
   return {
      width: Math.round(w),
      height: Math.round(h),
      x: isFinite(x) && x >= 0 ? Math.round(x) : null,
      y: isFinite(y) && y >= 0 ? Math.round(y) : null,
      userSaved: Number(values.userSaved) !== 0,
      fallback: true
   };
}

function aceReadWindowLayoutFallback() {
   var path = aceWindowLayoutFallbackPath();
   if (!path)
      return null;
   var f = new File;
   try {
      f.openForReading(path);
      var buffer = f.read(DataType_ByteArray, f.size);
      f.close();
      var text = typeof buffer.utf8ToString === "function" ? buffer.utf8ToString(0, buffer.length) : buffer.toString();
      return aceWindowLayoutFromText(text);
   } catch (error) {
      try {
         if (f.isOpen)
            f.close();
      } catch (closeError) {
      }
   }
   return null;
}

function aceWriteWindowLayoutFallback(size, pos, userSaved) {
   var path = aceWindowLayoutFallbackPath();
   if (!path || !size)
      return false;
   var text =
      "width=" + Math.round(size.width) + "\n" +
      "height=" + Math.round(size.height) + "\n" +
      "x=" + (pos && pos.x >= 0 ? Math.round(pos.x) : -1) + "\n" +
      "y=" + (pos && pos.y >= 0 ? Math.round(pos.y) : -1) + "\n" +
      "userSaved=" + (userSaved ? 1 : 0) + "\n";
   var f = new File;
   try {
      f.createForWriting(path);
      f.write(ByteArray.stringToUTF8(text));
      f.close();
      return true;
   } catch (error) {
      try {
         if (f.isOpen)
            f.close();
      } catch (closeError) {
      }
   }
   return false;
}

function aceClassifyWorkspace(size) {
   if (!size)
      return "UNKNOWN";
   if (size.width < ACE_DISPLAY_MIN_WIDTH || size.height < ACE_DISPLAY_MIN_HEIGHT)
      return "BELOW_MINIMUM";
   if (size.width < ACE_DISPLAY_MIN_WIDTH + ACE_DISPLAY_MARGIN_WIDTH || size.height < ACE_DISPLAY_MIN_HEIGHT + ACE_DISPLAY_MARGIN_HEIGHT)
      return "MARGINAL";
   return "OK";
}

function aceWindowSizeFitsWorkspace(size, workspace) {
   if (!size || !workspace)
      return true;
   return size.width <= workspace.width && size.height <= workspace.height;
}

function aceWindowPositionFitsWorkspace(pos, size, workspace) {
   if (!pos || !size || !workspace)
      return false;
   return pos.x >= 0 && pos.y >= 0 && pos.x + size.width <= workspace.width && pos.y + size.height <= workspace.height;
}

function aceLegacySavedWindowSizeLooksLikeDefault(saved) {
   if (!saved)
      return false;
   return saved.width === ACE_DISPLAY_MIN_WIDTH &&
      saved.height === ACE_DISPLAY_MIN_HEIGHT &&
      saved.x === null &&
      saved.y === null &&
      !saved.userSaved;
}

function aceLargestUsableDialogSize(workspace) {
   if (!workspace)
      return aceDefaultDialogSize();
   return {
      width: Math.max(640, Math.floor(workspace.width)),
      height: Math.max(480, Math.floor(workspace.height))
   };
}

function aceEstimateScalingText(dialog) {
   var ratios = [];
   var pixelRatio = aceGetOptionalDialogNumber(dialog, "devicePixelRatio");
   if (pixelRatio && pixelRatio > 0)
      ratios.push("devicePixelRatio " + Math.round(pixelRatio * 100) + "%");
   var scale = aceGetOptionalDialogNumber(dialog, "devicePixelRatioF");
   if (scale && scale > 0 && scale !== pixelRatio)
      ratios.push("devicePixelRatioF " + Math.round(scale * 100) + "%");
   return ratios.length ? ratios.join(", ") : "unavailable";
}

function aceBuildDisplayDiagnosticsLines(dialog, warningShown) {
   var workspace = aceGetDialogAvailableScreenSize(dialog);
   var preferredSize = aceAcmCompactDialogSizeForWorkspace(workspace);
   var classification = aceClassifyWorkspace(workspace);
   var currentW = dialog && dialog.width ? dialog.width : null;
   var currentH = dialog && dialog.height ? dialog.height : null;
   var saved = dialog && typeof dialog.readWindowSizePreference === "function" ? dialog.readWindowSizePreference() : null;
   return [
      "ACE Display Diagnostics",
      "",
      "ACE version: " + ACE_VERSION,
      "Platform: " + aceDisplayPlatformName(),
      "Available workspace: " + aceFormatScreenSizeForWarning(workspace) + " logical pixels",
      "ACE required minimum: " + ACE_DISPLAY_MIN_WIDTH + " x " + ACE_DISPLAY_MIN_HEIGHT + " logical pixels",
      "Preferred launch size: " + preferredSize.width + " x " + preferredSize.height + " logical pixels",
      "Minimum saved width on this platform: " + aceMinimumSavedWindowWidthForPlatform() + " logical pixels",
      "Current window: " + (currentW && currentH ? Math.round(currentW) + " x " + Math.round(currentH) : "unavailable") + " logical pixels",
      "Saved window: " + (saved ? saved.width + " x " + saved.height + (saved.x !== null && saved.y !== null ? " at " + saved.x + ", " + saved.y : "") : "none"),
      "Estimated display scaling: " + aceEstimateScalingText(dialog),
      "Mouse-wheel zoom: " + (dialog && dialog.mouseWheelZoomEnabled ? "on" : "off") + " (toggle with the Mouse Zoom checkbox in the header)",
      "Display classification: " + classification,
      "Warning shown this launch: " + (warningShown ? "yes" : "no"),
      "",
      "ACE uses one supported interface layout. It can be enlarged and a preferred window arrangement can be saved, but ACE does not switch to Standard, Compact, or Small-Screen layouts."
   ];
}

function aceBuildWorkspaceWarning(dialog, classification) {
   var workspace = aceGetDialogAvailableScreenSize(dialog);
   if (classification === "MARGINAL") {
      return "ACE is running close to its minimum recommended window size.\n\n" +
         "The interface should work, but some controls may feel crowded. For best results, maximize the ACE window, use a larger monitor, or reduce Windows display scaling if that remains comfortable for normal use.";
   }
   return "ACE requires more usable screen space than is currently available.\n\n" +
      "Your display may be physically large or high-resolution, but Windows display scaling or the current display environment may be reducing the logical workspace available to the application.\n\n" +
      "ACE uses one supported interface layout and does not provide separate Standard, Compact, or Small-Screen interface variants.\n\n" +
      "PixInsight reports available workspace as " + aceFormatScreenSizeForWarning(workspace) + " logical pixels. ACE requires at least " + ACE_DISPLAY_MIN_WIDTH + " x " + ACE_DISPLAY_MIN_HEIGHT + " logical pixels.\n\n" +
      "For best results, maximize the ACE window, reduce Windows display scaling if practical, or use a larger external monitor. You may continue, but some controls may appear crowded.";
}

function aceLogDisplayDiagnostics(dialog, warningShown) {
   if (!warningShown && !ACE_DEVELOPMENT_CONSOLE_LOGS_ENABLED && !ACE_DEBUG_CONTROLS_ENABLED)
      return;
   var lines = aceBuildDisplayDiagnosticsLines(dialog, warningShown);
   console.writeln("");
   for (var i = 0; i < lines.length; ++i)
      console.writeln(lines[i]);
}

function aceShowDocument(title, lines) {
   var dialog = new Dialog;
   dialog.windowTitle = title || ACE_TOOL_NAME;
   dialog.userResizable = true;

   var textBox = new TextBox(dialog);
   textBox.readOnly = true;
   textBox.wordWrapping = true;
   textBox.text = lines.join("\n");
   textBox.minWidth = 720;
   textBox.minHeight = 480;
   textBox.backgroundColor = ACE_COLORS.inset;
   textBox.textColor = ACE_COLORS.text;
   textBox.foregroundColor = ACE_COLORS.text;
   var docFont = new Font;
   docFont.family = "DejaVu Sans Mono";
   docFont.pixelSize = ACE_FONT_BODY;
   textBox.font = docFont;

   var resetDocumentToTop = function() {
      if (typeof textBox.setSelection === "function")
         textBox.setSelection(0, 0);
      if (typeof textBox.setCaretPosition === "function")
         textBox.setCaretPosition(0);
      if (typeof textBox.home === "function")
         textBox.home();
      textBox.cursorPosition = 0;
      textBox.caretPosition = 0;
      textBox.selectionStart = 0;
      textBox.selectionEnd = 0;
   };

   var closeButton = new PushButton(dialog);
   closeButton.text = "Close";
   closeButton.onClick = function() { dialog.ok(); };

   var buttons = new HorizontalSizer;
   buttons.addStretch();
   buttons.add(closeButton);

   dialog.sizer = new VerticalSizer;
   dialog.sizer.margin = 8;
   dialog.sizer.spacing = 8;
   dialog.sizer.add(textBox, 100);
   dialog.sizer.add(buttons);
   dialog.adjustToContents();
   resetDocumentToTop();
   dialog.onShow = function() {
      resetDocumentToTop();
   };
   dialog.execute();
}

function aceFaqDocument() {
   return [
      "ASTRO CONTRAST ENHANCER FAQ",
      "Version " + ACE_VERSION,
      "",
      "What is Astro Contrast Enhancer?",
      "Astro Contrast Enhancer is a free PixInsight JavaScript tool from Cosgrove's Cosmos. Patrick A. Cosgrove wrote ACE for his own astrophotography workflow and is sharing it widely as a protected, visual way to shape local contrast in stretched images.",
      "",
      "Is this a beta?",
      "Yes. ACE is a beta of a complex image-processing tool. The goal is a practical, reliable release, and feedback from real images is welcome, especially reports about responsiveness, artifacts, confusing behavior, or documentation gaps.",
      "",
      "What does ACE do?",
      "ACE separates local contrast work into Texture, Clarity, and Dehaze. Texture controls contrast of small-scale features. Clarity controls contrast of mid-scale structure. Dehaze works on broad veil, wash, and tonal depth. The controls are protected so stars, halos, smooth background, and risky dark patches are not pushed as aggressively as the structures you want to enhance.",
      "",
      "What is the basic workflow?",
      "Load a stretched RGB image, choose Stars Present or Starless, then start in Preview. Make small global Texture and Clarity changes first. Add Dehaze only when the image has broad veil or flatness. Inspect Before/After and diagnostic maps as needed. Use Local Selection for regions that need a different treatment. Commit local edits when they look right, then Save New Image or Apply to Target for full-resolution output.",
      "",
      "Should I use Stars Present or Starless?",
      "Use Stars Present when the source image still contains stars. This enables star and halo protection. Use Starless only when stars have already been removed or when you are processing a starless image.",
      "",
      "What does Texture do?",
      "Texture controls contrast of fine features such as small wisps, dust texture, ridges, filaments, and crisp local structure. It is not a deconvolution or traditional sharpening algorithm. Too much Texture can make noise, tiny star edges, or small artifacts more visible, so use the Texture Map and Before/After check to keep the result natural.",
      "",
      "What does Clarity do?",
      "Clarity controls mid-scale local contrast. It is designed for nebula folds, dust lanes, galaxy structure, reflection nebulosity, and broader but still structured detail. Internally, Clarity builds a protected mid-scale structure signal and uses tone-aware response so useful faint and midtone features can open up without simply crushing shadows or flattening bright regions. Advanced > Clarity Response offers Light, Balanced, and Strong behavior.",
      "",
      "What does Dehaze do?",
      "Positive Dehaze reduces broad veil, wash, or haze-like low-frequency flatness. Negative Dehaze can add back a softer haze character. ACE Dehaze is an astro-safe veil tool with highlight and compact-source protection, not just a large-radius contrast boost.",
      "",
      "What are the main controls?",
      "The Target selector chooses the PixInsight image. The Stars Present / Starless selector tells ACE how to treat stars. The Preview toolbar switches between the processed preview, diagnostic maps, lasso masks, star protection, and edit-area views. The three main sliders set global Texture, Clarity, and Dehaze. Advanced opens scale, response, Dehaze, and protection tuning. Protection toggles control background and star protection. Local Selection lets you draw, adjust, feather, invert, and commit lasso edits. Output buttons save or apply the final full-resolution result.",
      "",
      "What is Local Selection?",
      "Local Selection lets you draw a lasso and apply Texture, Clarity, or Dehaze locally. In normal mode, the adjustment applies inside the lasso. Invert applies the adjustment outside the lasso. Feather / Roll-off controls how softly the local edit blends into the surrounding image.",
      "",
      "What does the Pass Viewer show?",
      "The Pass Viewer summarizes the current output recipe. It shows whether a global adjustment is active and lists committed local passes in order. Rows show Texture, Clarity, and Dehaze values for each pass, so you can see what will be replayed when you save or apply the full-resolution result.",
      "",
      "What happens if I turn protection off?",
      "Turning off a protection family removes that restraint from preview and full-resolution output. Background Protection reduces changes in smooth sky, bright tonal plateaus, and artifact-prone low-signal regions. Star Protection reduces changes on stars and halos in Stars Present mode. With protections off, the sliders can hit harder, but backgrounds, stars, halos, and highlights can become less natural. Use protection-off comparisons deliberately, not as a default finishing state.",
      "",
      "What are the diagnostic maps?",
      "Texture Map shows the fine-scale feature signal that Texture is using. Clarity Map shows the mid-scale structure signal that Clarity is using. Dehaze Map shows the broad veil estimate. Delta Map shows the signed luminance change from the active adjustment: white means brighter, black means darker, and gray means mostly unchanged. These maps are diagnostic views, not final masks that must look pretty.",
      "",
      "How should I use the diagnostic maps?",
      "Use diagnostic maps to understand what ACE is responding to. Texture should correlate with fine structures. Clarity should correlate with broader folds, dust lanes, and mid-scale form. Dehaze should be smooth and broad. Delta is the best view for asking, 'What did this adjustment actually change?' The Before/After button can also be used from diagnostic views to compare against the preview image and stay grounded in the actual region being inspected.",
      "",
      "What does Before/After do?",
      "Hold the Before/After control or the C / Cmd-C shortcut to show the before state while held; release to return to the adjusted state. In diagnostic views, Before/After can show the preview image so the map can be interpreted against the real image content.",
      "",
      "What does the Detail Loupe do?",
      "Detail Loupe is enabled by default. Hold Shift over the Preview image to inspect source-detail data in a larger loupe panel. The loupe uses a target-style cursor, suppresses normal preview tooltips while active, and supports momentary Before/After with C or Cmd-C while the key is held.",
      "",
      "Why does ACE sometimes show a central working message?",
      "ACE uses draft previews for responsiveness and source-detail views for inspection. Some operations, such as the first committed high-zoom detail view after a large local edit, can take several seconds. ACE should show a central working message only when a real wait is expected. Ordinary cached pan and zoom inspection should stay quiet and responsive.",
      "",
      "Does final output use preview data?",
      "No. Save New Image and Apply to Target rebuild from the original full-resolution source using the current global settings, committed local edits, protection settings, and Advanced settings. Preview caps do not limit final output quality.",
      "",
      "What should I watch for?",
      "Watch stars, halos, smooth backgrounds, and faint nebulosity. If stars look harsh, use Stars Present mode and stronger protection. If backgrounds look dirty, reduce Clarity or Dehaze, increase Protection Strength, or use Local Selection for a narrower edit.",
      "",
      "What is the best way to learn ACE?",
      "Use it like a finishing tool. Make small changes, check Before/After often, inspect diagnostic maps when something feels surprising, and build local passes only where the image asks for them. The best results usually come from several restrained decisions rather than one extreme slider move."
   ];
}

function aceTechnicalDocument() {
   return [
      "ASTRO CONTRAST ENHANCER TECHNICAL APPENDIX",
      "Version " + ACE_VERSION,
      "",
      "1. Free Beta Tool from Cosgrove's Cosmos",
      "Astro Contrast Enhancer is a free PixInsight JavaScript tool from Cosgrove's Cosmos. Patrick A. Cosgrove wrote it for his own astrophotography work and is sharing it as a beta so other imagers can use it, test it, and help improve it.",
      "",
      "ACE is a complex protected local-contrast environment. It is intended for careful visual finishing, not one-click processing. Feedback is welcome, especially when real-world images reveal confusing behavior, artifacts, slow interactions, or unclear controls.",
      "",
      "2. What ACE Is For",
      "ACE is designed for stretched RGB astrophotography images. It helps shape contrast at three spatial scales while protecting image areas that are easy to damage.",
      "",
      "The three main adjustment families are:",
      "  - Texture: small-scale feature contrast.",
      "  - Clarity: mid-scale structure and depth.",
      "  - Dehaze: broad veil, wash, and tonal/color depth.",
      "",
      "ACE is not a replacement for calibration, denoising, deconvolution, star processing, masks, curves, HDR tools, or expert PixInsight workflows. It is a finishing-stage tool for protected visual contrast shaping.",
      "",
      "3. Main Interface Walkthrough",
      "Target chooses the PixInsight image ACE will load. Stars Present / Starless tells ACE whether star and halo protection should be active. Use Stars Present for normal star-containing images and Starless for starless data.",
      "",
      "The Preview toolbar selects what the main image area shows. Preview is the processed image. Texture, Clarity, Dehaze, and Delta are diagnostic maps. Lasso, Star, and Edit Area show selection and protection masks when meaningful. The Before/After control provides a momentary comparison. Zoom buttons move between Fit and inspection zoom levels.",
      "",
      "The Enhancement panel contains the three main sliders. Texture, Clarity, and Dehaze can be used globally or inside a Local Selection. Reset returns the main sliders to zero. Advanced opens expert controls for scale, Clarity response, Dehaze behavior, and protection strength.",
      "",
      "The Protection panel controls background and star protection. The Local Selection panel provides New, Clear, Commit, Invert, Refine, Expand, Contract, Feather / Roll-off, Protected Overlay, and Detail Loupe. The Pass Viewer summarizes the active output recipe. The Output panel saves or applies the result and saves diagnostic masks.",
      "",
      "4. A Practical Enhancement Workflow",
      "Start in Preview at Fit to judge the whole image and set Stars Present or Starless correctly. Fit is useful for overall balance, but it is not always useful for judging fine detail. Texture works at a very small scale, often around a few source pixels, so its effect can be visually lost when the image is downsampled to Fit.",
      "",
      "For Texture, zoom into an inspection view or hold Shift to use the Detail Loupe. The loupe lets you check whether fine structure improves without making noise, small artifacts, or star edges harsh. This is especially important before committing local Texture edits.",
      "",
      "Clarity and Dehaze are easier to judge at most zoom levels because they operate on broader structures. Clarity affects mid-scale folds, dust lanes, galaxy arms, and nebular form. Dehaze affects broad wash, veil, and tonal depth. You can often judge their overall direction at Fit, then confirm the result at a closer zoom.",
      "",
      "A good sequence is: set the input mode, make broad Clarity or Dehaze decisions while viewing the whole image, inspect Texture with zoom or the loupe, then use Local Selection for regions that need a different treatment.",
      "",
      "Use Before/After frequently. If a slider helps one part of the image but hurts another, reset or reduce the global value and use Local Selection for the region that needs more work. Keep local passes modest and commit them when they are correct. Use the Pass Viewer to track the recipe before saving full-resolution output.",
      "",
      "5. Texture Computation",
      "Texture controls contrast of fine-scale features. Conceptually, ACE compares luminance against a small-radius smoothed version and uses the difference as a fine structure signal:",
      "  Texture layer ~= luminance - blur(luminance, Texture Scale)",
      "",
      "The Texture slider controls the strength and sign of this fine structure response. Positive values increase small-scale contrast; negative values soften it. Texture Scale is measured in source-image pixels and defaults to 3 px. Star, halo, background, and artifact-risk protections restrain the response where fine contrast is likely to look unnatural.",
      "",
      "6. Clarity Computation",
      "Clarity is the most structure-aware middle scale control in ACE. It is built from a mid-scale luminance signal, then shaped by tone, confidence, and protection terms so the response is not merely a blunt high-pass contrast expansion.",
      "",
      "Conceptually:",
      "  Clarity structure ~= luminance - blur(luminance, Clarity Scale)",
      "",
      "The protected Clarity path separates useful midtone and faint-ridge lift from risky dark trough growth. Positive Clarity tends to open folds, dust lanes, and broad structure; negative Clarity can soften or reduce mid-scale contrast. Clarity Response controls how readily the structure signal opens: Light is restrained, Balanced is the default, and Strong opens galaxy and dust-lane response earlier while still using protection.",
      "",
      "Clarity Scale is measured in source-image pixels and defaults to 12 px. Smaller values move Clarity toward finer local structure. Larger values make it respond to broader mid-scale features.",
      "",
      "7. Dehaze Computation",
      "Dehaze estimates a broad veil field rather than simply applying a large-radius sharpening pass. Positive Dehaze reduces broad wash and can add tonal/color separation. Negative Dehaze adds back a softer haze character.",
      "",
      "Dehaze Scale defaults to 120 px and defines the broad veil field radius in source-image pixels. Veil Strength scales the correction. Highlight Guard controls how conservatively bright nebulosity, star cores, and highlights are protected. A value of 100 is the standard guard; lower values let bright regions participate more, while higher values protect them more strongly.",
      "",
      "8. Protection Controls",
      "Background Protection reduces contrast changes in smooth sky, bright tonal plateaus, and low-confidence regions where local contrast can create dirty backgrounds or artificial dark holes. Star Protection reduces changes on compact stars and halos when Stars Present mode is active.",
      "",
      "Protection Strength is a master scale for enabled protection families. 100 is the standard strength. Lower values open the enabled protections and allow stronger changes. Higher values make enabled protections more conservative. Turning a protection checkbox off removes that protection family from both preview and full-resolution output; it does not just hide an overlay.",
      "",
      "9. Local Selection and Pass Viewer",
      "Local Selection creates a feathered lasso weight map. In normal mode, the inside of the lasso is active and the outside is protected. In inverted mode, the outside is active and the inside is protected. Feather / Roll-off sets the transition width.",
      "",
      "Commit stores the lasso geometry, feather value, invert state, slider values, protection settings, Advanced settings, and algorithm version. The Pass Viewer lists the global state and committed local passes in order. Rows such as L1 T+40 C+20 show the local pass number and its Texture, Clarity, and Dehaze values. Save New Image and Apply to Target replay this recipe on the original full-resolution source.",
      "",
      "10. Detail Loupe and Inspection Zoom",
      "Detail Loupe is enabled by default. Hold Shift over the Preview image to inspect a larger source-detail view around the cursor. The loupe is meant to make local decisions easier without changing the main zoom level. It supports momentary Before/After with C or Cmd-C while the key is held.",
      "",
      "At 200% and above, ACE may request source-detail data for the visible image field. After committed local edits, ACE can build a full-resolution committed-result cache. The first build can take a few seconds; later pan and zoom inspection should crop from that cache and stay responsive.",
      "",
      "11. Diagnostic Maps",
      "Texture Map shows the fine-scale feature signal Texture is using. It should correlate with small wisps, fine dust, filaments, and crisp local structure. It is not a star mask, noise mask, or final output image.",
      "",
      "Clarity Map shows the mid-scale structure signal Clarity is using. It should correlate with broader folds, dust lanes, galaxy arms, and other mid-scale features. It is useful for checking whether Clarity is responding to the intended structures.",
      "",
      "Dehaze Map shows the broad veil estimate. It is expected to look smooth and low-frequency. Bright areas indicate stronger estimated veil or wash; dark areas indicate less.",
      "",
      "Delta Map shows the signed luminance change caused by the active adjustment. White means brighter, black means darker, and gray means mostly unchanged. Delta is often the clearest diagnostic for understanding what a slider or local pass is actually doing.",
      "",
      "The Before/After control can be used from diagnostic views to compare against the preview image, which helps ground a map in the actual region being inspected.",
      "",
      "12. Advanced Controls",
      "Scale tab: Texture Scale defaults to 3 px, Clarity Scale defaults to 12 px, and Dehaze Scale defaults to 120 px. These are source-image pixel radii that define the approximate scale each tool responds to.",
      "",
      "Clarity tab: Clarity Response offers Light, Balanced, and Strong behavior. Balanced is the default. Strong opens useful midtone and dust-lane response earlier; Light is more restrained.",
      "",
      "Dehaze tab: Veil Strength scales the broad-veil correction. Highlight Guard controls protection of bright nebulosity, highlights, and star cores. 100 is the standard guard.",
      "",
      "Protection tab: Protection Strength controls how conservative enabled protections are. 100 is standard. Lower values open enabled protections; higher values make them stronger.",
      "",
      "Opening Advanced does not change the image. Moving an Advanced control changes behavior. Defaults restores the active tab to the standard settings. Advanced values remain active while you work and are stored with committed local edits.",
      "",
      "13. Preview, Detail, and Full-Resolution Output",
      "The preview pipeline is optimized for interaction. Draft preview data keeps slider exploration responsive. Source-detail crops and committed-result caches are used for inspection when zoomed in. Processed preview updates must cover the visible image field; ACE should not paint a partial processed rectangle over a broader draft image.",
      "",
      "Save New Image and Apply to Target rebuild from the original full-resolution source using the current global adjustment, committed local passes, protection state, and Advanced settings. Preview resolution does not limit final output quality.",
      "",
      "14. Release Summary for " + ACE_VERSION,
      "This beta build focuses on release-readiness: quieter normal console behavior, clearer user documentation, protected full-field preview updates, improved high-zoom committed-detail caching, default Detail Loupe behavior, momentary Before/After consistency, readable Pass Viewer rows, and UI polish for command feedback and Advanced value display.",
      "",
      "Known practical guidance: use ACE gradually, inspect before/after often, keep protections on unless you have a reason to compare without them, and report cases where maps, responsiveness, or output quality do not match expectations."
   ];
}

