AstroContrastEnhancerDialog.prototype.refreshLocalSelectionControls = function() {
   var lassoEnabled = this.processingMode === "lasso";
   var hasSelection = this.hasLassoSelection();
   var hasSource = this.hasActiveSource();
   var hasPending = !!(this.appState && this.appState.cache && this.appState.cache.pendingActive);
   var committedLocalCount = this.appState && this.appState.editRecipe ? this.appState.editRecipe.length : 0;
   var canUndo = !!(this.appState && this.appState.undoStack && this.appState.undoStack.length);
   var canRedo = !!(this.appState && this.appState.redoStack && this.appState.redoStack.length);
   var canCommit = lassoEnabled &&
      hasSelection &&
      this.appState &&
      this.appState.cache &&
      this.appState.cache.pendingActive &&
      this.appState.params &&
      this.appState.params.hasEffect();
   var geometryActionsReady = hasSelection &&
      !this.selectionTransitionBusy &&
      !this.pendingLassoStatusText &&
      !this.lassoDrawing &&
      !this.lassoMoving;
   if (this.newLassoButton)
      this.newLassoButton.setVisualEnabled(hasSource);
   if (this.newLassoButton)
      this.newLassoButton.setActive(!!this.localSelectionNewActive);
   if (this.clearButton)
      this.clearButton.setVisualEnabled(hasSource && (lassoEnabled || hasSelection || !!this.localSelectionNewActive || hasPending || committedLocalCount > 0));
   if (this.invertButton)
      this.invertButton.setVisualEnabled(geometryActionsReady);
   if (this.refineButton)
      this.refineButton.setVisualEnabled(geometryActionsReady);
   if (this.expandLassoButton)
      this.expandLassoButton.setVisualEnabled(geometryActionsReady);
   if (this.contractLassoButton)
      this.contractLassoButton.setVisualEnabled(geometryActionsReady);
   if (this.commitButton)
      this.commitButton.setVisualEnabled(canCommit);
   if (this.commitButton && !canCommit)
      this.commitButton.setActive(false);
   if (this.cancelEditButton)
      this.cancelEditButton.setVisualEnabled(hasPending);
   if (this.undoButton)
      this.undoButton.setVisualEnabled(canUndo);
   if (this.redoButton)
      this.redoButton.setVisualEnabled(canRedo);
   if (this.protectedOverlayCheck)
      this.protectedOverlayCheck.enabled = lassoEnabled;
   if (this.protectedOverlayIntensity)
      this.protectedOverlayIntensity.enabled = lassoEnabled;
   if (this.featherSlider)
      this.featherSlider.setEnabled(lassoEnabled);
   if (this.saveCurrentMaskButton)
      this.saveCurrentMaskButton.setVisualEnabled(this.currentMaskViewCanSave() && this.viewModeAvailability(this.appState.preview.viewMode || "preview").available);
   if (this.passViewerHost)
      this.refreshPassViewerIfChanged();
};

function aceSignedSliderToken(prefix, value) {
   var v = Math.round(value || 0);
   if (v === 0)
      return "";
   return prefix + (v > 0 ? "+" : "") + v;
}

function aceSummarizeEffectParamsCompact(params) {
   if (!params)
      return "None";
   var parts = [];
   var t = aceSignedSliderToken("T", params.texture || 0);
   var c = aceSignedSliderToken("C", params.clarity || 0);
   var d = aceSignedSliderToken("D", params.dehaze || 0);
   if (t)
      parts.push(t);
   if (c)
      parts.push(c);
   if (d)
      parts.push(d);
   return parts.length ? parts.join(" ") : "None";
}

function aceSummarizeLocalPassDetail(edit) {
   var points = edit && edit.lassoPoints ? edit.lassoPoints.length : 0;
   var feather = Math.round(edit && edit.feather ? edit.feather : 0);
   var prefix = edit && edit.inverted ? "Inv " : "";
   return prefix + aceSummarizeEffectParamsCompact(edit ? edit.params : null) + " | " + points + "pt F" + feather;
}

function acePassViewerRow(parent, text, color, tooltip) {
   var row = new Control(parent);
   row.aceText = text || "";
   row.aceColor = color || ACE_COLORS.text;
   row.toolTip = tooltip || text || "";
   aceFixHeight(row, ACE_HOST_IS_WINDOWS ? 17 : 16);
   row.onPaint = function() {
      var g = new Graphics(this);
      g.brush = new Brush(ACE_COLORS.inset);
      g.pen = new Pen(ACE_COLORS.lineDim);
      g.drawRect(this.boundsRect);
      var f = new Font;
      f.pixelSize = ACE_HOST_IS_WINDOWS ? 13 : 11;
      g.font = f;
      g.pen = new Pen(this.aceColor);
      var bulletColor = this.aceColor;
      g.brush = new Brush(bulletColor);
      g.fillRect(5, Math.max(4, Math.round((this.height - 7) * 0.5)), 7, 7);
      var text = this.aceText;
      var maxWidth = Math.max(20, this.width - 20);
      while (text.length > 3 && f.width(text) > maxWidth)
         text = text.substring(0, text.length - 4) + "...";
      var y = Math.round((this.height + f.ascent - f.descent) * 0.5) - 1;
      g.drawText(16, y, text);
      g.end();
   };
   return row;
}

function acePassViewerDeleteControl(parent, localIndex, label, callback) {
   var control = new Control(parent);
   aceFixHeight(control, ACE_HOST_IS_WINDOWS ? 17 : 16);
   control.setFixedWidth(24);
   control.localIndex = localIndex;
   control.toolTip = "Remove " + label;
   control.cursor = new Cursor(StdCursor_PointingHand);
   control.onMousePress = function() {
      if (callback)
         callback(this.localIndex);
   };
   control.onPaint = function() {
      var g = new Graphics(this);
      g.brush = new Brush(ACE_COLORS.inset);
      g.pen = new Pen(ACE_COLORS.lineDim, 1);
      g.drawRect(this.boundsRect);
      var cx = Math.round(this.width * 0.5);
      var cy = Math.round(this.height * 0.5);
      var r = Math.max(5, Math.min(7, Math.floor(Math.min(this.width, this.height) * 0.42)));
      g.brush = new Brush(0xff3b2522);
      g.pen = new Pen(0xffd8dcff, 1);
      g.drawCircle(cx, cy, r);
      g.pen = new Pen(0xffffd6cc, 2);
      g.drawLine(cx - r + 3, cy - r + 3, cx + r - 3, cy + r - 3);
      g.drawLine(cx + r - 3, cy - r + 3, cx - r + 3, cy + r - 3);
      g.end();
   };
   return control;
}

function acePassViewerActionRow(parent, row, callback) {
   var control = new Control(parent);
   control.aceRow = row;
   control.aceCallback = callback;
   control.toolTip = row.toolTip || row.text || "";
   aceFixHeight(control, ACE_HOST_IS_WINDOWS ? 17 : 16);
   control.cursor = new Cursor(row.canDelete || row.action ? StdCursor_PointingHand : StdCursor_Arrow);
   control.onMousePress = function(x, y) {
      var r = this.aceRow || {};
      var hitDelete = r.canDelete && x >= this.width - 25;
      if (this.aceCallback)
         this.aceCallback(r, hitDelete);
   };
   control.onPaint = function() {
      var r = this.aceRow || {};
      var g = new Graphics(this);
      g.brush = new Brush(ACE_COLORS.inset);
      g.pen = new Pen(ACE_COLORS.lineDim, 1);
      g.drawRect(this.boundsRect);
      var color = r.color || ACE_COLORS.text;
      g.brush = new Brush(color);
      var yDot = Math.max(4, Math.round((this.height - 7) * 0.5));
      g.fillRect(6, yDot, 7, yDot + 7);
      var font = new Font;
      font.pixelSize = ACE_HOST_IS_WINDOWS ? 13 : 11;
      g.font = font;
      g.pen = new Pen(color);
      var maxTextWidth = Math.max(24, this.width - (r.canDelete ? 44 : 20));
      var text = aceFitTextToWidth(font, String(r.text || ""), maxTextWidth);
      var ty = Math.round((this.height + font.ascent - font.descent) * 0.5) - 1;
      g.drawText(18, ty, text);
      if (r.canDelete) {
         var cx = this.width - 13;
         var cy = Math.round(this.height * 0.5);
         var rr = Math.max(5, Math.min(7, Math.floor(Math.min(this.width, this.height) * 0.42)));
         g.brush = new Brush(0xff3b2522);
         g.pen = new Pen(0xffd8dcff, 1);
         g.drawCircle(cx, cy, rr);
         g.pen = new Pen(0xffffd6cc, 2);
         g.drawLine(cx - rr + 3, cy - rr + 3, cx + rr - 3, cy + rr - 3);
         g.drawLine(cx + rr - 3, cy - rr + 3, cx - rr + 3, cy + rr - 3);
      }
      g.end();
   };
   return control;
}

AstroContrastEnhancerDialog.prototype.passViewerRowsForState = function() {
   var rows = [];
   if (!this.appState)
      return rows;
   var committedGlobal = this.appState.globalParams &&
      EffectParameters.prototype.hasEffect.call(this.appState.globalParams);
   if (committedGlobal) {
      var globalSummary = aceSummarizeEffectParamsCompact(this.appState.globalParams);
      rows.push({
         kind: "global",
         text: "Global " + globalSummary,
         toolTip: "Committed global: " + globalSummary,
         color: ACE_COLORS.detail,
         canDelete: false
      });
   } else if (this.processingMode === "full" && this.appState.params &&
              EffectParameters.prototype.hasEffect.call(this.appState.params)) {
      var liveSummary = aceSummarizeEffectParamsCompact(this.appState.params);
      rows.push({
         kind: "live-global",
         text: "Live " + liveSummary,
         toolTip: "Current full-image adjustment: " + liveSummary + ". Commit or save output to make it part of the recipe.",
         color: ACE_COLORS.warning,
         canDelete: false
      });
   }

   var recipe = this.appState.editRecipe || [];
   for (var i = 0; i < recipe.length; ++i) {
      var edit = recipe[i];
      if (!edit || edit.type !== "lasso")
         continue;
      var localSummary = aceSummarizeEffectParamsCompact(edit.params);
      rows.push({
         kind: "local",
         localIndex: i,
         text: "L" + (i + 1) + " " + localSummary,
         toolTip: "Committed local pass " + (i + 1) + ": " + aceSummarizeLocalPassDetail(edit),
         color: ACE_COLORS.accent,
         canDelete: true
      });
   }

   if (this.appState.cache && this.appState.cache.pendingActive) {
      var pendingSummary = aceSummarizeEffectParamsCompact(this.appState.params);
      rows.push({
         kind: "pending",
         text: "Pending " + pendingSummary,
         toolTip: "Uncommitted local edit preview: " + pendingSummary + ". Use Commit to add it to the recipe.",
         color: ACE_COLORS.warning,
         canDelete: false
      });
   }
   return rows;
};

AstroContrastEnhancerDialog.prototype.refreshPassViewer = function() {
   if (!this.passViewerHost)
      return;
   if (this.passViewerBody) {
      this.passViewerHost.sizer.remove(this.passViewerBody);
      this.passViewerBody.hide();
   }
   this.passViewerBody = new Control(this.passViewerHost);
   this.passViewerBody.sizer = new VerticalSizer;
   this.passViewerBody.sizer.margin = 0;
   this.passViewerBody.sizer.spacing = 1;
   this.passViewerHost.sizer.add(this.passViewerBody, 100);
   this.passViewerRows = [];
   var rows = this.passViewerRowsForState();
   this.passViewerLastSignature = this.passViewerSignature(rows);
   var localCount = 0;
   var pendingCount = 0;
   for (var i = 0; i < rows.length; ++i) {
      if (rows[i].kind === "local")
         ++localCount;
      else if (rows[i].kind === "pending")
         ++pendingCount;
   }
   var self = this;
   if (!rows.length) {
      this.passViewerPageStart = 0;
      this.passViewerBody.sizer.add(acePassViewerRow(this.passViewerBody, "No committed passes", ACE_COLORS.muted, "No committed global or local passes"));
   } else {
      var visibleRows = rows;
      if (rows.length > ACE_PASS_VIEWER_MAX_VISIBLE_ROWS) {
         var head = [];
         var startIndex = 0;
         if (rows[0].kind === "global" || rows[0].kind === "live-global") {
            head.push(rows[0]);
            startIndex = 1;
         }
         var workingRows = rows.slice(startIndex);
         var navSlots = workingRows.length > (ACE_PASS_VIEWER_MAX_VISIBLE_ROWS - head.length) ? 1 : 0;
         var pageSlots = Math.max(1, ACE_PASS_VIEWER_MAX_VISIBLE_ROWS - head.length - navSlots);
         var maxStart = Math.max(0, workingRows.length - pageSlots);
         if (this.passViewerPageStart === undefined || this.passViewerPageStart === null)
            this.passViewerPageStart = 0;
         this.passViewerPageStart = aceClamp(Math.round(this.passViewerPageStart), 0, maxStart);
         visibleRows = head.slice(0);
         if (this.passViewerPageStart > 0) {
            visibleRows.push({
               kind: "page-newer",
               action: "page-newer",
               step: pageSlots,
               maxStart: maxStart,
               text: "Previous passes",
               toolTip: "Show the previous page of committed local passes.",
               color: ACE_COLORS.warning,
               canDelete: false
            });
         }
         var first = this.passViewerPageStart;
         var last = Math.min(workingRows.length, first + pageSlots);
         for (var vr = first; vr < last; ++vr)
            visibleRows.push(workingRows[vr]);
         if (last < workingRows.length && visibleRows.length < ACE_PASS_VIEWER_MAX_VISIBLE_ROWS) {
            visibleRows.push({
               kind: "page-older",
               action: "page-older",
               step: pageSlots,
               maxStart: maxStart,
               text: "More passes",
               toolTip: "Show the next page of committed local passes.",
               color: ACE_COLORS.warning,
               canDelete: false
            });
         }
      }
      for (var r = 0; r < visibleRows.length; ++r) {
         var rowControl = acePassViewerActionRow(this.passViewerBody, visibleRows[r], function(row, hitDelete) {
            if (hitDelete && row.canDelete)
               self.removeCommittedLocalPass(row.localIndex);
            else if (row.action) {
               var step = Math.max(1, row.step || 1);
               var maxStart = Math.max(0, row.maxStart || 0);
               if (row.action === "page-older")
                  self.passViewerPageStart = aceClamp((self.passViewerPageStart || 0) + step, 0, maxStart);
               else if (row.action === "page-newer")
                  self.passViewerPageStart = aceClamp((self.passViewerPageStart || 0) - step, 0, maxStart);
               self.passViewerLastSignature = "";
               self.refreshPassViewer();
               self.refreshPreviewStatus(self.describeLoadedSource(), row.action === "page-older" ? "Pass viewer: more passes" : "Pass viewer: previous passes");
            }
            else
               self.refreshPreviewStatus(self.describeLoadedSource(), row.toolTip || row.text || "Pass viewer");
         });
         this.passViewerBody.sizer.add(rowControl);
         this.passViewerRows.push(rowControl);
      }
   }
   if (this.passViewerSummaryLine) {
      var globalActive = this.appState && this.appState.globalParams &&
         EffectParameters.prototype.hasEffect.call(this.appState.globalParams);
      var summary = (globalActive ? "Global" : "No global") + " | " + localCount + " local" + (localCount === 1 ? "" : "s");
      if (pendingCount)
         summary += " | pending";
      this.passViewerSummaryLine.setStatus(summary, pendingCount ? ACE_COLORS.warning : ACE_COLORS.accent);
   }
};

AstroContrastEnhancerDialog.prototype.passViewerSignature = function(rows) {
   rows = rows || this.passViewerRowsForState();
   var parts = [String(this.passViewerPageStart || 0)];
   for (var i = 0; i < rows.length; ++i)
      parts.push(rows[i].kind + ":" + (rows[i].localIndex !== undefined ? rows[i].localIndex : "") + ":" + rows[i].text + ":" + (rows[i].canDelete ? "1" : "0"));
   return parts.join("|");
};

AstroContrastEnhancerDialog.prototype.refreshPassViewerIfChanged = function() {
   if (!this.passViewerHost)
      return;
   var rows = this.passViewerRowsForState();
   var signature = this.passViewerSignature(rows);
   if (signature === this.passViewerLastSignature)
      return;
   this.refreshPassViewer();
};

AstroContrastEnhancerDialog.prototype.refreshWindowSizeReadout = function(prefix) {
   if (!this.windowSizeLine)
      return;
   var size = this.currentWindowSize();
   var label = ACE_HOST_IS_WINDOWS ? ("Win " + size.width + "x" + size.height) : ("Win " + size.width + " x " + size.height);
   if (prefix) {
      var bareSize = ACE_HOST_IS_WINDOWS ? (size.width + "x" + size.height) : (size.width + " x " + size.height);
      label = prefix + " " + bareSize;
   }
   this.windowSizeLine.setStatus(label, prefix ? ACE_COLORS.active : ACE_COLORS.accent, !!prefix, prefix ? 0xff24331f : ACE_COLORS.inset);
};

AstroContrastEnhancerDialog.prototype.refreshWindowSizeButtons = function() {
   var saved = this.readWindowSizePreference();
   var size = this.currentWindowSize();
   var sessionSaved = this.sessionSavedWindowSize || null;
   var savedCurrent = !!(
      (saved && saved.userSaved && saved.width === size.width && saved.height === size.height) ||
      (sessionSaved && sessionSaved.width === size.width && sessionSaved.height === size.height)
   );
   if (this.saveWindowSizeButton)
      this.saveWindowSizeButton.setActive(savedCurrent);
   if (this.resetWindowSizeButton)
      this.resetWindowSizeButton.setActive(false);
};

AstroContrastEnhancerDialog.prototype.refreshResponsiveWindowsPresentation = function() {
   if (!ACE_HOST_IS_WINDOWS)
      return;
   var width = this.width || aceDefaultDialogSize().width;
   var roomy = width >= 1540;
   if (this.aceWindowsRoomyPresentation === roomy)
      return;
   this.aceWindowsRoomyPresentation = roomy;
   if (this.titleControl && typeof this.titleControl.setRoomyWindows === "function")
      this.titleControl.setRoomyWindows(roomy);
   if (this.inputModeGroup) {
      this.inputModeGroup.scaledMinWidth = roomy ? 184 : 176;
      this.inputModeGroup.update();
   }
   if (this.imageTypeModeLine) {
      this.imageTypeModeLine.scaledMinWidth = roomy ? 172 : 166;
      this.imageTypeModeLine.update();
   }
   if (this.windowSizeGroup) {
      this.windowSizeGroup.scaledMinWidth = roomy ? 134 : 128;
      this.windowSizeGroup.update();
   }
   if (this.windowSizeLine) {
      this.windowSizeLine.scaledMinWidth = roomy ? 124 : 118;
      this.windowSizeLine.update();
   }
   if (this.mouseZoomGroup) {
      this.mouseZoomGroup.scaledMinWidth = roomy ? 82 : 78;
      this.mouseZoomGroup.update();
   }
   if (this.sourceCombo) {
      this.sourceCombo.minWidth = roomy ? 300 : 280;
      this.sourceCombo.update();
   }
   if (this.beforeAfterPill) {
      this.beforeAfterPill.aceText = "Before/After";
      this.beforeAfterPill.aceShortcutText = "";
      this.beforeAfterPill.scaledMinWidth = 160;
      this.beforeAfterPill.minWidth = 160;
      this.beforeAfterPill.maxWidth = 160;
      this.beforeAfterPill.aceTextOffsetX = 0;
      this.beforeAfterPill.update();
   }
   if (this.zoomToolbarButtons) {
      for (var z = 0; z < this.zoomToolbarButtons.length; ++z) {
         var button = this.zoomToolbarButtons[z];
         if (!button)
            continue;
         button.scaledMinWidth = button.aceToolbarName === "Fit" ? (roomy ? 56 : 52) : (roomy ? 48 : 44);
         button.update();
      }
   }
   if (this.displayDiagnosticsButton) {
      this.displayDiagnosticsButton.aceText = roomy ? "Display" : "Disp";
      this.displayDiagnosticsButton.scaledMinWidth = roomy ? 62 : 46;
      this.displayDiagnosticsButton.update();
   }
   if (this.techAppendixButton) {
      this.techAppendixButton.aceText = roomy ? "Tech Appx" : "Tech";
      this.techAppendixButton.scaledMinWidth = roomy ? 96 : 72;
      this.techAppendixButton.update();
   }
   if (this.responsiveToolbarButtons) {
      for (var i = 0; i < this.responsiveToolbarButtons.length; ++i) {
         var button = this.responsiveToolbarButtons[i];
         if (!button)
            continue;
         button.aceText = roomy ? button.aceRoomyText : button.aceCompactText;
         button.scaledMinWidth = roomy ? button.aceRoomyWidth : button.aceCompactWidth;
         button.update();
      }
   }
};

AstroContrastEnhancerDialog.prototype.readWindowSizePreference = function() {
   var fallbackSaved = aceReadWindowLayoutFallback();
   if (fallbackSaved && fallbackSaved.userSaved)
      return fallbackSaved;
   if (typeof Settings !== "undefined") {
      try {
         var w = aceReadSettingInt(ACE_SETTING_WINDOW_WIDTH);
         var h = aceReadSettingInt(ACE_SETTING_WINDOW_HEIGHT);
         if (w && h)
         {
            var x = aceReadSettingInt(ACE_SETTING_WINDOW_X);
            var y = aceReadSettingInt(ACE_SETTING_WINDOW_Y);
            var settingsSaved = {
               width: Math.round(w),
               height: Math.round(h),
               x: x !== null && x >= 0 ? x : null,
               y: y !== null && y >= 0 ? y : null,
               userSaved: aceReadSettingBool(ACE_SETTING_WINDOW_SAVED_BY_USER),
               fallback: false
            };
            return settingsSaved;
         }
      } catch (error) {
      }
   }
   return fallbackSaved;
};

AstroContrastEnhancerDialog.prototype.restoreWindowPositionIfSafe = function(saved, size, workspace) {
   if (!saved || saved.x === null || saved.y === null)
      return false;
   if (!aceWindowPositionFitsWorkspace({ x: saved.x, y: saved.y }, size, workspace))
      return false;
   try {
      if (typeof this.move === "function") {
         this.move(saved.x, saved.y);
         return true;
      }
   } catch (error) {
   }
   return false;
};

AstroContrastEnhancerDialog.prototype.applySavedWindowSize = function() {
   var workspace = aceGetDialogAvailableScreenSize(this);
   var defaultSize = aceAcmCompactDialogSizeForWorkspace(workspace);
   var saved = this.readWindowSizePreference();
   var selected = null;
   var canUseSaved = aceSavedWindowSizeIsUsableForPlatform(saved) &&
      !aceLegacySavedWindowSizeLooksLikeDefault(saved) &&
      aceWindowSizeFitsWorkspace(saved, workspace);
   if (canUseSaved)
      selected = { width: saved.width, height: saved.height };
   else if (aceWindowSizeFitsWorkspace(defaultSize, workspace))
      selected = defaultSize;
   else
      selected = aceLargestUsableDialogSize(workspace);
   if (selected.width < ACE_DISPLAY_MIN_WIDTH || selected.height < ACE_DISPLAY_MIN_HEIGHT) {
      this.setMinWidth(Math.max(320, selected.width));
      this.setMinHeight(Math.max(320, selected.height));
   }
   this.resize(selected.width, selected.height);
   if (saved && selected.width === saved.width && selected.height === saved.height)
      this.restoreWindowPositionIfSafe(saved, selected, workspace);
};

AstroContrastEnhancerDialog.prototype.currentWindowSize = function() {
   var defaultSize = aceDefaultDialogSize();
   var w = aceGetOptionalDialogNumber(this, "width");
   var h = aceGetOptionalDialogNumber(this, "height");
   if (w && h)
      return {
         width: Math.round(w),
         height: Math.round(h)
      };
   var rect = aceGetOptionalDialogRect(this, "boundsRect") ||
      aceGetOptionalDialogRect(this, "rect") ||
      aceGetOptionalDialogRect(this, "frameRect");
   if (rect && rect.width > 0 && rect.height > 0)
      return {
         width: Math.round(rect.width),
         height: Math.round(rect.height)
      };
   return {
      width: Math.round(this.width || defaultSize.width),
      height: Math.round(this.height || defaultSize.height)
   };
};

AstroContrastEnhancerDialog.prototype.saveWindowSizePreference = function() {
   var size = this.currentWindowSize();
   if (size.width < ACE_DISPLAY_MIN_WIDTH || size.height < ACE_DISPLAY_MIN_HEIGHT) {
      aceMessage("ACE cannot save this window size because it is below the supported minimum interface size.", ACE_TOOL_NAME + " Window Layout", StdIcon_Warning);
      this.setFooterStatus("Window size not saved: below supported minimum");
      return;
   }
   if (size.width < aceMinimumSavedWindowWidthForPlatform()) {
      aceMessage("ACE cannot save this Windows window width because the toolbar and header controls become crowded at this size. Please widen the ACE window before saving the layout.", ACE_TOOL_NAME + " Window Layout", StdIcon_Warning);
      this.setFooterStatus("Window size not saved: too narrow for Windows layout");
      return;
   }
   var pos = aceGetDialogPosition(this);
   var fallbackSaved = aceWriteWindowLayoutFallback(size, pos, true);
   if (typeof Settings !== "undefined") {
      try {
         aceWriteSettingInt(ACE_SETTING_WINDOW_WIDTH, size.width);
         aceWriteSettingInt(ACE_SETTING_WINDOW_HEIGHT, size.height);
         if (pos) {
            aceWriteSettingInt(ACE_SETTING_WINDOW_X, pos.x);
            aceWriteSettingInt(ACE_SETTING_WINDOW_Y, pos.y);
         }
         else {
            aceWriteSettingInt(ACE_SETTING_WINDOW_X, -1);
            aceWriteSettingInt(ACE_SETTING_WINDOW_Y, -1);
         }
         aceWriteSettingBool(ACE_SETTING_WINDOW_SAVED_BY_USER, true);
         aceFlushSettingsIfSupported();
         this.sessionSavedWindowSize = { width: size.width, height: size.height };
         this.setFooterStatus("Window layout saved");
      } catch (error) {
         this.sessionSavedWindowSize = { width: size.width, height: size.height };
         this.setFooterStatus(fallbackSaved ? "Window layout saved" : "Window size set for this session");
      }
   } else {
      this.sessionSavedWindowSize = { width: size.width, height: size.height };
      this.setFooterStatus(fallbackSaved ? "Window layout saved" : "Window size set for this session");
   }
   this.refreshWindowSizeReadout("Saved");
   this.refreshWindowSizeButtons();
};

AstroContrastEnhancerDialog.prototype.resetWindowSizeDefault = function() {
   var workspace = aceGetDialogAvailableScreenSize(this);
   var defaultSize = aceAcmCompactDialogSizeForWorkspace(workspace);
   var selected = aceWindowSizeFitsWorkspace(defaultSize, workspace) ? defaultSize : aceLargestUsableDialogSize(workspace);
   if (selected.width < ACE_DISPLAY_MIN_WIDTH || selected.height < ACE_DISPLAY_MIN_HEIGHT) {
      this.setMinWidth(Math.max(320, selected.width));
      this.setMinHeight(Math.max(320, selected.height));
   } else {
      this.setMinWidth(ACE_DISPLAY_MIN_WIDTH);
      this.setMinHeight(ACE_DISPLAY_MIN_HEIGHT);
   }
   this.resize(selected.width, selected.height);
   if (typeof Settings !== "undefined") {
      try {
         aceWriteSettingInt(ACE_SETTING_WINDOW_WIDTH, defaultSize.width);
         aceWriteSettingInt(ACE_SETTING_WINDOW_HEIGHT, defaultSize.height);
         aceWriteSettingInt(ACE_SETTING_WINDOW_X, -1);
         aceWriteSettingInt(ACE_SETTING_WINDOW_Y, -1);
         aceWriteSettingBool(ACE_SETTING_WINDOW_SAVED_BY_USER, false);
         aceFlushSettingsIfSupported();
      } catch (error) {
      }
   }
   aceWriteWindowLayoutFallback(defaultSize, null, false);
   this.sessionSavedWindowSize = null;
   this.refreshWindowSizeReadout("Default");
   this.refreshWindowSizeButtons();
   if (this.preview)
      this.preview.update();
   this.setFooterStatus("Default window layout restored");
};

AstroContrastEnhancerDialog.prototype.refreshMouseWheelZoomUi = function() {
   if (!this.mouseWheelZoomCheck)
      return;
   var enabled = !!this.mouseWheelZoomEnabled;
   this.mouseWheelZoomCheck.checked = enabled;
   this.mouseWheelZoomCheck.toolTip = enabled ?
      "Mouse-wheel zoom is on. Wheel movement over the Preview image changes zoom." :
      "Mouse-wheel zoom is off. Enable this to let wheel movement zoom the Preview image.";
   this.mouseWheelZoomCheck.update();
};

AstroContrastEnhancerDialog.prototype.setMouseWheelZoomEnabled = function(enabled, showStatus) {
   this.mouseWheelZoomEnabled = !!enabled;
   aceWriteSettingBool(ACE_SETTING_MOUSE_WHEEL_ZOOM_ENABLED, this.mouseWheelZoomEnabled);
   this.refreshMouseWheelZoomUi();
   if (showStatus !== false) {
      var status = "Mouse-wheel zoom " + (this.mouseWheelZoomEnabled ? "enabled" : "disabled");
      this.setFooterStatus(status);
      this.refreshPreviewStatus(this.describeLoadedSource(), status);
   }
   if (this.preview)
      this.preview.update();
};

AstroContrastEnhancerDialog.prototype.showDisplayDiagnostics = function() {
   aceShowDocument("Display Diagnostics", aceBuildDisplayDiagnosticsLines(this, !!this.displayWarningShown));
};

AstroContrastEnhancerDialog.prototype.showWorkspaceWarningIfNeeded = function() {
   var workspace = aceGetDialogAvailableScreenSize(this);
   var classification = aceClassifyWorkspace(workspace);
   this.displayClassification = classification;
   this.displayWarningShown = false;
   if (classification === "OK" || classification === "UNKNOWN")
      return;
   if (classification === "MARGINAL" && aceReadSettingBool(ACE_SETTING_MARGINAL_WARNING_DISMISSED))
      return;
   this.displayWarningShown = true;
   if (classification === "MARGINAL") {
      var answer = (new MessageBox(
         aceBuildWorkspaceWarning(this, classification) + "\n\nDismiss this marginal workspace warning for future launches?",
         ACE_TOOL_NAME + " Display Notice",
         StdIcon_Information,
         StdButton_Yes,
         StdButton_No
      )).execute();
      if (answer === StdButton_Yes)
         aceWriteSettingBool(ACE_SETTING_MARGINAL_WARNING_DISMISSED, true);
   } else {
      aceMessage(aceBuildWorkspaceWarning(this, classification), ACE_TOOL_NAME + " Display Warning", StdIcon_Warning);
   }
};

AstroContrastEnhancerDialog.prototype.refreshImageTypeReadout = function() {
   if (!this.imageTypeModeLine)
      return;
   var starsMode = this.inputType === "stars";
   this.imageTypeModeLine.setStatus(
      starsMode ? "Mode: Stars Present" : "Mode: Starless",
      starsMode ? ACE_COLORS.warning : ACE_COLORS.accent,
      true,
      starsMode ? 0xff3a2e14 : 0xff242f38
   );
};

AstroContrastEnhancerDialog.prototype.refreshDebugControlsVisibility = function() {
   var visible = !!this.debugControlsVisible;
   var textureComparisonVisible = visible || ACE_TEXTURE_COMPARISON_CONTROLS_ENABLED;
   if (this.algorithmDebugPanel)
      aceSetCollapsed(this.algorithmDebugPanel, !textureComparisonVisible);
   if (this.textureModeSelector)
      aceSetCollapsed(this.textureModeSelector, !textureComparisonVisible);
   if (this.clarityModeSelector)
      aceSetCollapsed(this.clarityModeSelector, !visible);
   if (this.dehazeModeSelector)
      aceSetCollapsed(this.dehazeModeSelector, !visible);
   if (this.clarityDebugButtons) {
      for (var cb = 0; cb < this.clarityDebugButtons.length; ++cb)
         aceSetCollapsed(this.clarityDebugButtons[cb], true);
   }
   if (this.saveMaskAuditButton)
      aceSetCollapsed(this.saveMaskAuditButton, !visible);
   if (this.saveComputeAuditButton)
      aceSetCollapsed(this.saveComputeAuditButton, !visible);
   if (this.fullTimingAuditButton)
      aceSetCollapsed(this.fullTimingAuditButton, !visible);
   if (this.globalTimingAuditButton)
      aceSetCollapsed(this.globalTimingAuditButton, !visible);
   if (this.responseTimeAuditButton)
      aceSetCollapsed(this.responseTimeAuditButton, !visible);
   if (this.performanceFlowAuditButton)
      aceSetCollapsed(this.performanceFlowAuditButton, !visible);
   this.refreshTextureModeUi();
   this.refreshClarityModeUi();
   this.refreshDehazeAppModeUi();
   this.refreshPreviewStatus(this.describeLoadedSource(), visible ? "Diagnostics shown" : "Diagnostics hidden");
   if (this.preview)
      this.preview.update();
};

